def transfer(db,sender,receiver,amount):
    if not (sender in db and receiver in db):
        raise ValueError("missing accounts")
    if sender == receiver:
        raise ValueError("same accounts")
    if isinstance(amount, bool) or not isinstance(amount, int):
        raise ValueError("noninteger amount")
    if amount <= 0:
        raise ValueError("positive integer amount")
    result = {a.id: a.balance for a in db}
    for account in [sender, receiver]:
        if account in result:
            result[account.id] = result[account.id] - amount
    return result

